-- 业务叶子与外部接口的一对多绑定。
-- 一条记录 = 某个叶子上的一次页面调用，使用哪个接口系统的哪条具体接口。
--
-- 现有业务表的 deleted 是 smallint（0/1）。不要写 FALSE，也不要写 B'0'。
-- 若上一版已经把本表的 deleted 建成 bit，下面会改成 int2。

CREATE TABLE IF NOT EXISTS "sub_system_api_binding" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "biz_sub_system_id" bigint NOT NULL,
    "workshop_code" varchar(100) NOT NULL DEFAULT '',
    "scene" varchar(64) NOT NULL,
    "api_sub_system_id" bigint NOT NULL,
    "endpoint_id" bigint NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" int2 NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = 'sub_system_api_binding'
          AND column_name = 'deleted'
          AND udt_name = 'bit'
    ) THEN
        ALTER TABLE "sub_system_api_binding" ALTER COLUMN "deleted" DROP DEFAULT;
        ALTER TABLE "sub_system_api_binding"
            ALTER COLUMN "deleted" TYPE int2
            USING (CASE WHEN "deleted"::text IN ('1', 't', 'true') THEN 1 ELSE 0 END);
        ALTER TABLE "sub_system_api_binding" ALTER COLUMN "deleted" SET DEFAULT 0;
        ALTER TABLE "sub_system_api_binding" ALTER COLUMN "deleted" SET NOT NULL;
    END IF;
END $$;

COMMENT ON TABLE "sub_system_api_binding" IS '业务叶子的外部接口绑定：一个叶子可绑定多次页面调用';
COMMENT ON COLUMN "sub_system_api_binding"."biz_sub_system_id" IS '业务系统 ID';
COMMENT ON COLUMN "sub_system_api_binding"."workshop_code" IS '叶子编号';
COMMENT ON COLUMN "sub_system_api_binding"."scene" IS '页面调用：account_sync/user_register/employee_query/role_assign/role_create/role_query';
COMMENT ON COLUMN "sub_system_api_binding"."api_sub_system_id" IS '接口所在系统 ID';
COMMENT ON COLUMN "sub_system_api_binding"."endpoint_id" IS '具体接口 ID';

-- 保存绑定走 @KeySequence，主键取 nextval('sub_system_api_binding_seq')。
-- IDENTITY 只会建 sub_system_api_binding_id_seq，不会建这个序列。
-- 序列不存在时，打开页面能查出数据，点保存就报「表或字段缺失」。
CREATE SEQUENCE IF NOT EXISTS "sub_system_api_binding_seq";
SELECT setval(
    '"sub_system_api_binding_seq"',
    GREATEST(COALESCE((SELECT MAX("id") FROM "sub_system_api_binding"), 0), 1)
);

-- 现网页面调用都走 Camstar（api_type = camstar），按下表把每个业务叶子绑到该系统里用途相同的接口。
-- 接口系统只取一条：优先「仅接口目标」（说明含「非 JUMP 门户」或名称含 Camstar，如 Camstar人员管理）；
-- 没有这种记录时，取任意 camstar 配置里编号最小的一条。http 及其他类型不参与。
-- 同一用途有多条接口时，用已启用、排序最前、编号最小的那条。
-- 某个用途在 Camstar 上还没有接口行时，这一条场景先不插，补上接口后重跑 INSERT 即可。
-- 已有未删除绑定的不覆盖。
-- deleted 用 ::text 比较，smallint 和 bit 都能过。

INSERT INTO "sub_system_api_binding"
    ("biz_sub_system_id", "workshop_code", "scene", "api_sub_system_id", "endpoint_id", "creator", "updater")
SELECT leaf."biz_sub_system_id",
       leaf."workshop_code",
       scene."scene",
       cam."sub_system_id",
       ep."id",
       'upgrade',
       'upgrade'
FROM (
    SELECT w."sub_system_id" AS "biz_sub_system_id",
           COALESCE(NULLIF(BTRIM(w."workshop_code"), ''), '') AS "workshop_code"
    FROM "sub_system_workshop" w
    WHERE w."deleted"::text IN ('0', 'f', 'false')
      AND w."sub_system_id" IS NOT NULL
    GROUP BY w."sub_system_id", COALESCE(NULLIF(BTRIM(w."workshop_code"), ''), '')
) leaf
CROSS JOIN (
    VALUES
        ('account_sync', 'update'),
        ('user_register', 'create'),
        ('employee_query', 'query'),
        ('role_assign', 'update'),
        ('role_create', 'role_create'),
        ('role_query', 'role_query')
) AS scene("scene", "purpose")
CROSS JOIN (
    SELECT c."sub_system_id"
    FROM "sub_system_api_config" c
    JOIN "sub_system" s ON s."id" = c."sub_system_id" AND s."deleted"::text IN ('0', 'f', 'false')
    WHERE c."api_type" = 'camstar'
      AND c."deleted"::text IN ('0', 'f', 'false')
    ORDER BY
        CASE
            WHEN COALESCE(s."description", '') LIKE '%非 JUMP 门户%'
              OR COALESCE(s."system_name", '') ILIKE '%camstar%' THEN 0
            ELSE 1
        END,
        c."sub_system_id"
    LIMIT 1
) cam
JOIN LATERAL (
    SELECT e."id"
    FROM "sub_system_api_endpoint" e
    WHERE e."sub_system_id" = cam."sub_system_id"
      AND e."purpose" = scene."purpose"
      AND e."deleted"::text IN ('0', 'f', 'false')
      AND (e."enabled" IS NULL OR e."enabled"::text IN ('1', 't', 'true'))
    ORDER BY e."sort" NULLS LAST, e."id"
    LIMIT 1
) ep ON TRUE
WHERE NOT EXISTS (
    SELECT 1
    FROM "sub_system_api_binding" b
    WHERE b."biz_sub_system_id" = leaf."biz_sub_system_id"
      AND b."workshop_code" = leaf."workshop_code"
      AND b."scene" = scene."scene"
      AND b."deleted"::text IN ('0', 'f', 'false')
);

-- 同步域账号/刷卡卡号走已有的「修改人员」(purpose=update)，不使用凭空加的 account_update。
-- 已经绑到 account_update 的，改到同一接口系统的修改人员接口。
UPDATE "sub_system_api_binding" b
SET "endpoint_id" = e."id",
    "updater" = 'upgrade',
    "update_time" = CURRENT_TIMESTAMP
FROM "sub_system_api_endpoint" e
WHERE b."scene" = 'account_sync'
  AND b."deleted"::text IN ('0', 'f', 'false')
  AND e."sub_system_id" = b."api_sub_system_id"
  AND e."purpose" = 'update'
  AND e."deleted"::text IN ('0', 'f', 'false')
  AND (e."enabled" IS NULL OR e."enabled"::text IN ('1', 't', 'true'))
  AND b."endpoint_id" IS DISTINCT FROM e."id";
